package com.medtrack.inventory.entity;
import com.medtrack.user.entity.User; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="inventory_journal_entries") public class InventoryJournalEntry { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="entry_number",nullable=false,unique=true) private String entryNumber; @Enumerated(EnumType.STRING) @Column(name="entry_type",nullable=false) private JournalEntryType entryType; @Column(name="reference_entity_type",nullable=false) private String referenceEntityType; @Column(name="reference_entity_id",nullable=false) private UUID referenceEntityId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="performed_by",nullable=false) private User performedBy; @Column(nullable=false) private String description; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt=Instant.now(); @OneToMany(mappedBy="journalEntry",cascade=CascadeType.ALL,orphanRemoval=true) private List<InventoryLedgerLine> lines=new ArrayList<>(); protected InventoryJournalEntry(){} public InventoryJournalEntry(String number,JournalEntryType type,String refType,UUID refId,User actor,String description){entryNumber=number;entryType=type;referenceEntityType=refType;referenceEntityId=refId;performedBy=actor;this.description=description;} public void addLine(InventoryLedgerLine line){line.setJournalEntry(this);lines.add(line);} public UUID getId(){return id;} public String getEntryNumber(){return entryNumber;} public List<InventoryLedgerLine> getLines(){return List.copyOf(lines);} }
